1: import { Injectable } from '@angular/core';
2: import { HttpBackend, HttpClient, HttpHeaders } from '@angular/common/http';
3: import { environment } from '../environments/environment';
4: import { catchError, map } from 'rxjs/operators';
5: import { HttpErrorManager } from './errorManager'
6: 
7: /**
8:  * This class manage the http connections with internal REST services. Use the response format {
9:  *  Code: 'xxxxx',
10:  *  Body: 'Some Data' (this element is returned if the request is success)
11:  *  ...
12:  * }
13:  */
14: @Injectable({
15:   providedIn: 'root',
16: })
17: export class RequestManager {
18:   private path!: any;
19:   public httpOptions: any;
20:   private readonly rawHttp: HttpClient;
21:   constructor(private readonly http: HttpClient, private readonly errManager: HttpErrorManager, httpBackend: HttpBackend) {
22:     this.rawHttp = new HttpClient(httpBackend);
23:     const acces_token = window.localStorage.getItem('access_token');
24:     if (acces_token !== null) {
25:       this.httpOptions = {
26:          headers: new HttpHeaders({
27:            'Content-Type': 'application/json',
28:            'Authorization': `Bearer ${acces_token}`,
29:          }),
30:       }
31:     }
32:   }
33: 
34: 
35:   /**
36:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
37:    * @param service: string
38:    */
39:   public setPath(service: string) {
40:     this.path = environment[service as keyof typeof environment];
41:   }
42: 
43: 
44:   /**
45:    * Perform a GET http request
46:    * @param endpoint service's end-point
47:    * @param params (an Key, Value object with que query params for the request)
48:    * @returns Observable<any>
49:    */
50:   get(endpoint: any) {
51:     return this.http.get<any>(`${this.path}${endpoint}`, this.httpOptions).pipe(
52:       map(
53:         (res) => {
54:           if (res.hasOwnProperty('Body')) {
55:             return res;
56:           } else {
57:             return res;
58:           }
59:         },
60:       ),
61:       catchError(this.errManager.handleError.bind(this)),
62:     );
63:   }
64: 
65:   /**
66:    * Perform a GET http request expecting an XML response
67:    * @param endpoint service's end-point
68:    * @returns Observable<string>
69:    */
70:   getXml(endpoint: any) {
71:     const acces_token = window.localStorage.getItem('access_token');
72:     const headers = acces_token
73:       ? new HttpHeaders({ 'Authorization': `Bearer ${acces_token}` })
74:       : new HttpHeaders();
75: 
76:     return this.http.get(`${this.path}${endpoint}`, {
77:       headers,
78:       responseType: 'text'
79:     }).pipe(
80:       catchError(this.errManager.handleError.bind(this)),
81:     );
82:   }
83: 
84:   /**
85:    * Perform a POST http request
86:    * @param endpoint service's end-point
87:    * @param element data to send as JSON
88:    * @returns Observable<any>
89:    */
90:   post(endpoint: any, element: any) {
91:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
92:       catchError(this.errManager.handleError),
93:     );
94:   }
95: 
96:   /**
97:    * Perform a POST http request for FormData
98:    * @param endpoint service's end-point
99:    * @param element FormData to send
100:    * @returns Observable<any>
101:    */
102:   post_file(endpoint: any, element: FormData) {
103:     const acces_token = window.localStorage.getItem('access_token');
104:     const headers = acces_token
105:       ? new HttpHeaders({ 'Authorization': `Bearer ${acces_token}` })
106:       : new HttpHeaders();
107:     
108:     return this.http.post<any>(`${this.path}${endpoint}`, element, { headers }).pipe(
109:       catchError(this.errManager.handleError),
110:     );
111:   }
112: 
113:   post_file_without_spinner(endpoint: any, element: FormData) {
114:     const acces_token = window.localStorage.getItem('access_token');
115:     const headers = acces_token
116:       ? new HttpHeaders({ 'Authorization': `Bearer ${acces_token}` })
117:       : new HttpHeaders();
118: 
119:     return this.rawHttp.post<any>(`${this.path}${endpoint}`, element, { headers }).pipe(
120:       catchError(this.errManager.handleError),
121:     );
122:   }
123: 
124:   /**
125:    * Perform a PUT http request
126:    * @param endpoint service's end-point
127:    * @param element data to send as JSON, With the id to UPDATE
128:    * @returns Observable<any>
129:    */
130:   put(endpoint: any, element: { Id: any; }) {
131:     const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
132:     return this.http.put<any>(path, element, this.httpOptions).pipe(
133:       catchError(this.errManager.handleError),
134:     );
135:   }
136: 
137:   /**
138:    * Perform a DELETE http request
139:    * @param endpoint service's end-point
140:    * @param id element's id for remove
141:    * @returns Observable<any>
142:    */
143:   delete(endpoint: any, id: any) {
144:     return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
145:       catchError(this.errManager.handleError),
146:     );
147:   }
148: };

